import pandas as pd, numpy as np, os
base = "/workspace/491f90ae-d8c7-47e8-baba-5e913f27c4ab"
files = {
    ("C","crutch"): f"{base}/sim_bo_C_crutch.csv",
    ("C","lander"): f"{base}/sim_bo_C_lander.csv",
    ("B","crutch"): f"{base}/sim_bo_B_crutch.csv",
    ("B","lander"): f"{base}/sim_bo_B_lander.csv",
}
dfs = {k: pd.read_csv(v) for k,v in files.items()}
for k,d in dfs.items():
    print(k, d.shape, list(d.columns))

# Confirm: spans match the user's claims. C ~3-4%, B ~2.5x. SEA spans for C:
for k,d in dfs.items():
    s = d['SEA_J_per_g']
    if s.notna().any():
        nz = s[s>0]
        if len(nz):
            print(k, "SEA ratio max/min =", round(nz.max()/nz.min(),2), "max=", nz.max(), "min=", nz.min())
        e = d['eta']
        print(k, "eta min/max:", round(e.min(),4), round(e.max(),4), "span:", round((e.max()-e.min()),5))
